using AiQuery.Application.Common;
using AiQuery.Application.Features.SoftwareCatalog;
using AiQuery.Infrastructure.Persistence;
using AiQuery.Infrastructure.Persistence.Records;
using Microsoft.EntityFrameworkCore;

namespace AiQuery.Infrastructure.Repositories;

internal sealed class EfCatalogStore(AppDbContext db) : ICatalogStore
{
    public async ValueTask<SoftwareDetail> CreateSoftwareAsync(Guid id, CreateSoftware c, CancellationToken ct)
    {
        var code = c.Code.Trim().ToLowerInvariant();
        if (await db.SoftwareProducts.IgnoreQueryFilters().AnyAsync(x => x.TenantId == c.TenantId && x.OwnerOrganizationId == c.OwnerOrganizationId && x.Code == code && !x.IsDeleted, ct)) throw new ApplicationConcurrencyException("software.code.conflict");
        var row = new SoftwareProductRecord { Id = id, TenantId = c.TenantId, OwnerOrganizationId = c.OwnerOrganizationId, Code = code, Name = c.Name.Trim(), Status = "Active", Version = 0 };
        db.Add(row); return Map(row, 0, "Missing");
    }
    public async ValueTask<SoftwareDetail?> GetSoftwareAsync(CatalogScope s, CancellationToken ct) { var row = await Scoped(s).AsNoTracking().SingleOrDefaultAsync(ct); return row is null ? null : Map(row, row.Versions.Count, "Derived"); }
    public async ValueTask<CatalogPage<SoftwareDetail>> ListSoftwareAsync(Guid tenantId, Guid? org, int page, int size, string? filter, string sort, bool desc, CancellationToken ct)
    {
        page = Math.Max(1, page); size = Math.Clamp(size, 1, 200); var q = db.SoftwareProducts.AsNoTracking().Where(x => x.TenantId == tenantId); if (org is not null) q = q.Where(x => x.OwnerOrganizationId == org); if (!string.IsNullOrWhiteSpace(filter)) q = q.Where(x => EF.Functions.ILike(x.Code, $"%{filter}%") || EF.Functions.ILike(x.Name, $"%{filter}%")); q = (sort, desc) switch { ("name", false) => q.OrderBy(x => x.Name), ("name", true) => q.OrderByDescending(x => x.Name), ("versionCount", false) => q.OrderBy(x => x.Versions.Count), ("versionCount", true) => q.OrderByDescending(x => x.Versions.Count), (_, true) => q.OrderByDescending(x => x.Code), _ => q.OrderBy(x => x.Code) }; var total = await q.LongCountAsync(ct); var rows = await q.Skip((page - 1) * size).Take(size).Select(x => new SoftwareDetail(x.Id, x.TenantId, x.OwnerOrganizationId, x.Code, x.Name, x.Status, x.Versions.Count, x.Versions.Any(v => v.Status == "Active") ? "Available" : "Missing", x.Version)).ToArrayAsync(ct); return new(rows, page, size, total);
    }
    public async ValueTask<SoftwareDetail> UpdateSoftwareAsync(UpdateSoftware c, bool? active, bool delete, CancellationToken ct) { var row = await Scoped(c.Scope).Include(x => x.Versions).SingleOrDefaultAsync(ct) ?? throw NotFound(); Concurrency(row.Version, c.Version); if (delete && row.Versions.Count > 0) throw new ApplicationConcurrencyException("software.delete.blocked"); row.Name = c.Name.Trim(); if (active is not null) row.Status = active.Value ? "Active" : "Inactive"; if (delete) row.IsDeleted = true; row.Version++; return Map(row, row.Versions.Count, "Derived"); }
    public async ValueTask<DatabaseDetail> CreateDatabaseAsync(Guid id, CreateDatabase c, CancellationToken ct) { await RequireSoftware(c.Scope, ct); await RequireVersions(c.Scope, c.IntroducedVersionId, c.RemovedVersionId, ct); var code = c.Code.Trim().ToLowerInvariant(); if (await db.SoftwareDatabases.AnyAsync(x => x.SoftwareProductId == c.Scope.SoftwareId && x.Code == code, ct)) throw new ApplicationConcurrencyException("database.code.conflict"); var row = new SoftwareDatabaseRecord { Id = id, TenantId = c.Scope.TenantId, SoftwareProductId = c.Scope.SoftwareId, Code = code, Name = c.Name.Trim(), Dialect = c.Dialect.Trim(), IntroducedVersionId = c.IntroducedVersionId, RemovedVersionId = c.RemovedVersionId, Version = 0 }; db.Add(row); return Map(row); }
    public async ValueTask<DatabaseDetail> UpdateDatabaseAsync(UpdateDatabase c, bool delete, CancellationToken ct) { await RequireSoftware(c.Scope, ct); var row = await db.SoftwareDatabases.SingleOrDefaultAsync(x => x.Id == c.DatabaseId && x.TenantId == c.Scope.TenantId && x.SoftwareProductId == c.Scope.SoftwareId, ct) ?? throw NotFound(); Concurrency(row.Version, c.Version); if (!delete) { await RequireVersions(c.Scope, c.IntroducedVersionId, c.RemovedVersionId, ct); row.Name = c.Name.Trim(); row.Dialect = c.Dialect.Trim(); row.IntroducedVersionId = c.IntroducedVersionId; row.RemovedVersionId = c.RemovedVersionId; } row.IsActive = !delete && c.IsActive; row.Version++; return Map(row); }
    public async ValueTask<CatalogPage<DatabaseDetail>> ListDatabasesAsync(CatalogScope s, int page, int size, CancellationToken ct) { await RequireSoftware(s, ct); page = Math.Max(1, page); size = Math.Clamp(size, 1, 200); var q = db.SoftwareDatabases.AsNoTracking().Where(x => x.TenantId == s.TenantId && x.SoftwareProductId == s.SoftwareId).OrderBy(x => x.Code); var total = await q.LongCountAsync(ct); var rows = await q.Skip((page - 1) * size).Take(size).ToArrayAsync(ct); return new(rows.Select(Map).ToArray(), page, size, total); }
    public async ValueTask<VersionDetail> CreateVersionAsync(Guid id, CreateVersion c, CancellationToken ct) { if (!await Scoped(c.Scope).AnyAsync(ct)) throw NotFound(); var label = c.Label.Trim(); if (await db.SoftwareVersions.AnyAsync(x => x.SoftwareProductId == c.Scope.SoftwareId && x.Label == label, ct)) throw new ApplicationConcurrencyException("version.label.conflict"); var row = new SoftwareVersionRecord { Id = id, SoftwareProductId = c.Scope.SoftwareId, Label = label, ReleaseDate = c.ReleaseDate, Status = "Active", Version = 0 }; db.Add(row); return Map(row, []); }
    public async ValueTask<VersionDetail> UpdateVersionAsync(UpdateVersion c, CancellationToken ct) { await RequireSoftware(c.Scope, ct); var row = await db.SoftwareVersions.Include(x => x.Dependencies).SingleOrDefaultAsync(x => x.Id == c.VersionId && x.SoftwareProductId == c.Scope.SoftwareId, ct) ?? throw NotFound(); Concurrency(row.Version, c.Version); if (row.Status == "Retired") throw new ApplicationConcurrencyException("version.retired.read_only"); row.ReleaseDate = c.ReleaseDate; row.Version++; return Map(row, row.Dependencies.Select(x => x.DependencyVersionId)); }
    public async ValueTask<VersionDetail> AddDependencyAsync(AddVersionDependency c, CancellationToken ct) { await RequireSoftware(c.Scope, ct); if (c.VersionId == c.DependencyId) throw new ApplicationConcurrencyException("version.dependency.self"); var versions = await db.SoftwareVersions.Where(x => x.SoftwareProductId == c.Scope.SoftwareId).Include(x => x.Dependencies).ToArrayAsync(ct); var row = versions.SingleOrDefault(x => x.Id == c.VersionId) ?? throw NotFound(); if (versions.All(x => x.Id != c.DependencyId)) throw new ApplicationAuthorizationException("version.dependency.cross_scope", "Dependency must belong to the same software."); var graph = versions.ToDictionary(x => x.Id, x => x.Dependencies.Select(d => d.DependencyVersionId).ToArray()); if (Reachable(c.DependencyId, c.VersionId, graph)) throw new ApplicationConcurrencyException("version.dependency.cycle"); if (row.Dependencies.All(x => x.DependencyVersionId != c.DependencyId)) row.Dependencies.Add(new() { SoftwareVersionId = row.Id, DependencyVersionId = c.DependencyId }); return Map(row, row.Dependencies.Select(x => x.DependencyVersionId)); }
    public async ValueTask<VersionDetail> RetireVersionAsync(CatalogScope s, Guid id, long version, CancellationToken ct) { await RequireSoftware(s, ct); var row = await db.SoftwareVersions.Include(x => x.Dependencies).SingleOrDefaultAsync(x => x.Id == id && x.SoftwareProductId == s.SoftwareId, ct) ?? throw NotFound(); Concurrency(row.Version, version); if (await db.PublicationPointers.AnyAsync(x => x.SoftwareVersionId == id && x.ActiveSnapshotId != null, ct)) throw new ApplicationConcurrencyException("version.retire.published_snapshot"); row.Status = "Retired"; row.Version++; return Map(row, row.Dependencies.Select(x => x.DependencyVersionId)); }
    public async ValueTask<CatalogPage<VersionDetail>> ListVersionsAsync(CatalogScope s, int page, int size, string? filter, CancellationToken ct) { await RequireSoftware(s, ct); page = Math.Max(1, page); size = Math.Clamp(size, 1, 200); var q = db.SoftwareVersions.AsNoTracking().Where(x => x.SoftwareProductId == s.SoftwareId); if (!string.IsNullOrWhiteSpace(filter)) q = q.Where(x => EF.Functions.ILike(x.Label, $"%{filter}%")); var total = await q.LongCountAsync(ct); var rows = await q.Include(x => x.Dependencies).OrderBy(x => x.Label).Skip((page - 1) * size).Take(size).ToArrayAsync(ct); return new(rows.Select(x => Map(x, x.Dependencies.Select(d => d.DependencyVersionId))).ToArray(), page, size, total); }
    private IQueryable<SoftwareProductRecord> Scoped(CatalogScope s) => db.SoftwareProducts.Where(x => x.Id == s.SoftwareId && x.TenantId == s.TenantId && (s.OrganizationId == null || x.OwnerOrganizationId == s.OrganizationId));
    private async Task RequireSoftware(CatalogScope scope, CancellationToken ct) { if (!await Scoped(scope).AnyAsync(ct)) throw NotFound(); }
    private async Task RequireVersions(CatalogScope s, Guid? introduced, Guid? removed, CancellationToken ct) { var ids = new[] { introduced, removed }.Where(x => x.HasValue).Select(x => x!.Value).ToArray(); if (ids.Length > 0 && await db.SoftwareVersions.CountAsync(x => x.SoftwareProductId == s.SoftwareId && ids.Contains(x.Id), ct) != ids.Distinct().Count()) throw new ApplicationAuthorizationException("database.version.cross_scope", "Availability versions must belong to software."); if (introduced is not null && removed is not null) { var order = await db.SoftwareVersions.Where(x => x.SoftwareProductId == s.SoftwareId).OrderBy(x => x.ReleaseDate).ThenBy(x => x.Label).Select(x => x.Id).ToArrayAsync(ct); if (Array.IndexOf(order, removed.Value) <= Array.IndexOf(order, introduced.Value)) throw new ApplicationConcurrencyException("database.version_range.invalid"); } }
    private static bool Reachable(Guid start, Guid target, IReadOnlyDictionary<Guid, Guid[]> graph) { var stack = new Stack<Guid>(); var seen = new HashSet<Guid>(); stack.Push(start); while (stack.Count > 0) { var x = stack.Pop(); if (x == target) return true; if (seen.Add(x) && graph.TryGetValue(x, out var next)) foreach (var n in next) stack.Push(n); } return false; }
    private static void Concurrency(long actual, long expected) { if (actual != expected) throw new ApplicationConcurrencyException("catalog.concurrency_conflict"); }
    private static ApplicationAuthorizationException NotFound() => new("catalog.not_found", "Catalog resource was not found in active scope.");
    private static SoftwareDetail Map(SoftwareProductRecord x, int count, string knowledge) => new(x.Id, x.TenantId, x.OwnerOrganizationId, x.Code, x.Name, x.Status, count, knowledge, x.Version); private static DatabaseDetail Map(SoftwareDatabaseRecord x) => new(x.Id, x.SoftwareProductId, x.Code, x.Name, x.Dialect, x.IntroducedVersionId, x.RemovedVersionId, x.IsActive, x.Version); private static VersionDetail Map(SoftwareVersionRecord x, IEnumerable<Guid> deps) => new(x.Id, x.SoftwareProductId, x.Label, x.ReleaseDate, x.Status, deps.ToArray(), "Derived", x.Version);
}
